def round_tax(taxable, rate):
    """按税率计算税额并保留两位小数。"""
    return round(taxable * rate, 2)

verification_tests:
from target import round_tax


def test_tax_at_exact_half_cent_rounds_up():
    assert round_tax(2.675, 1) == 2.68


def test_tax_below_half_cent_keeps_value():
    assert round_tax(2.674, 1) == 2.67


def test_tax_on_whole_amount():
